EOF_TOKEN = 'EOF'
EOF_SKIP = False

def read_all(path):
    with open(path, "rb") as f:
        return f.read()

def print_escaped(bs):
    out = ['"']
    for b in bs:
        if b == 92:
            out.append('\\\\')
        elif b == 34:
            out.append('\\\"')
        elif b == 10:
            out.append('\\n')
        elif b == 13:
            out.append('\\r')
        elif b == 9:
            out.append('\\t')
        elif b < 32 or b > 126:
            out.append(f'\\x{b:02X}')
        else:
            out.append(chr(b))
    out.append('"')
    return ''.join(out)

def main():
    if len(sys.argv) < 2:
        print(f"Usage: {sys.argv[0]} <input.txt>", file=sys.stderr)
        return 1
    try:
        data = read_all(sys.argv[1])
    except OSError:
        print(f"cannot read input file: {sys.argv[1]}", file=sys.stderr)
        return 1
    pos = 0
    line = 1
    col = 1
    n = len(data)
    while pos < n:
        state = 0
        last_tok = -1
        i = pos
        scan_line, scan_col = line, col
        last_pos = pos
        last_line, last_col = line, col
        while i < n:
            ch = data[i]
            nxt = DFA_TRANS[state][ch]
            if nxt < 0:
                break
            state = nxt
            i += 1
            if ch == 10:
                scan_line += 1
                scan_col = 1
            else:
                scan_col += 1
            if DFA_ACCEPT[state] >= 0:
                last_tok = DFA_ACCEPT[state]
                last_pos = i
                last_line = scan_line
                last_col = scan_col
        if last_tok >= 0:
            if not TOKEN_SKIP[last_tok]:
                print(f"TOKEN {TOKEN_NAMES[last_tok]} {print_escaped(data[pos:last_pos])} (line {line}, col {col})")
            pos = last_pos
            line = last_line
            col = last_col
        else:
            print(f"LEXICAL_ERROR line {line} col {col}: {print_escaped(data[pos:pos+1])}")
            if data[pos] == 10:
                line += 1
                col = 1
            else:
                col += 1
            pos += 1
    if EOF_TOKEN is not None and not EOF_SKIP:
        print(f'TOKEN {EOF_TOKEN} "<EOF>" (line {line}, col {col})')
    return 0

if __name__ == "__main__":
    raise SystemExit(main())
